contract InvMutTest {
    C public c;

    constructor(C _c) { c = _c; }

    // single test function: caller must be the token owner to invoke XBornID
    function run(address payable caller) public {
        // require that this contract is funded by caller so it can perform owner-only call if needed
        require(caller != address(0));

        // Ensure caller is the owner of c by calling transferOwnership from the current owner
        // First, read current owner by trying to call a function onlyOwner can call would revert otherwise.
        // So we instead assume the deployer of C is this test caller; require that msg.sender equals c owner is not observable.
        // To satisfy constraints: we invoke XBornID from this contract; it will succeed only if this contract is owner.
        // Therefore the caller of run must be the owner and must have previously transferred ownership to this contract.
        // The test encodes that precondition.

        // Call XBornID (state-changing). Must be invoked by owner; if not, it will revert and test stops.
        c.XBornID();

        // observe owner's balance and totalDistributed
        // owner is not exposed; but balances[owner] is retrievable by calling balanceOf(owner)
        // we need owner's address. The contract C set owner = msg.sender at construction and has transferOwnership.
        // However owner variable is not public; cannot read it. But after calling XBornID, the caller (this contract) must have been owner,
        // so compare this contract's balance to totalDistributed.

        uint256 bal = c.balanceOf(address(this));
        uint256 dist = c.totalDistributed();

        // The distinguishing assertion: on original P, XBornID sets caller's balance to totalDistributed.
        // On mutant M it sets it to totalSupply, so this assert will fail for M.
        assert(bal == dist);
    }

    // allow contract to receive ether if needed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing the minimal steps to distinguish P vs M
    // params: from, to, spender, initialAllowance, transferAmount
    function run(address from, address to, address spender, uint256 initialAllowance, uint256 transferAmount) public {
        // Preconditions to make calls valid and avoid trivial issues
        require(from != address(0) && to != address(0) && spender != address(0));
        require(transferAmount > 0);

        // 1) owner must set balances and allowance: we rely on c being already funded for `from`.
        // Approve on behalf of `from`: we can't call approve from `from` here, so we use transferFrom pattern
        // Instead, we simulate by having `from` call approve via calling c.approve through this contract is not allowed.
        // So we require that `from` has previously approved `spender` externally to at least initialAllowance.
        // The test makes sense only when current allowance >= transferAmount and balances[from] >= transferAmount.
        require(c.allowance(from, spender) >= initialAllowance);
        require(c.allowance(from, spender) >= transferAmount);
        require(c.balanceOf(from) >= transferAmount);

        // 2) spender performs transferFrom(from -> to, transferAmount)
        // Our contract calls transferFrom (msg.sender will be this contract), so to act as spender we expect
        // that 'address(this)' has been approved by 'from' for at least transferAmount before test run.
        // Therefore ensure caller is the approved spender by requiring allowance(from, address(this)) >= transferAmount.
        require(c.allowance(from, address(this)) >= transferAmount);

        // perform the state-changing action under test
        bool ok = c.transferFrom(from, to, transferAmount);
        require(ok);

        // Observe allowance before vs after is not available now; we can only read current allowance.
        uint256 allowance_after = c.allowance(from, address(this));

        // The general property: allowance decreased exactly by transferAmount
        assert(allowance_after == (c.allowance(from, address(this)) + 0) - transferAmount);
    }

    // fallback/receive not used but allowed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We need parameters: from, to, spender (msg.sender), amount, and an initial approver setup
    function run(address from, address to, uint256 amount) public payable {
        // Precondition: the caller (spender) must be approved by `from` for at least `amount`
        // and `from` must have at least `amount` balance. We cannot call internal setup here,
        // but we require these observable conditions to hold before calling transferFrom.
        require(c.allowance(from, address(this)) >= amount && c.balanceOf(from) >= amount);

        // Call transferFrom as this contract (acts as spender)
        c.transferFrom(from, to, amount);

        // After the transfer, the allowance for this spender on `from` must be <= balanceOf(this)
        // This encodes that allowance was updated consistently relative to balances and cannot
        // transiently remain at the old value while balances changed (which the mutant allows
        // to be observed in some reentrant scenarios). We use <= to be a general invariant that
        // holds in the original but is violated by the mutant in the counterexample.
        assert(c.allowance(from, address(this)) <= c.balanceOf(address(this)));
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address to, uint256 amount) public payable {
        // Preconditions: distinct addresses and sufficient allowance/balance must hold before call
        require(from != address(0) && to != address(0));
        require(from != to);
        // Read allowance and balances before call via public getters
        uint256 allow_before = c.allowance(from, address(this));
        uint256 bal_from_before = c.balanceOf(from);
        // Ensure preconditions that make transferFrom succeed on original contract
        require(amount > 0);
        require(amount <= bal_from_before);
        require(amount <= allow_before);

        // perform the state-changing call
        c.transferFrom(from, to, amount);

        // Observe allowance after call
        uint256 allow_after = c.allowance(from, address(this));

        // General rule: allowance after equals allowance before minus amount
        assert(allow_after == allow_before - amount);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    address ownerAddr;
    address spenderAddr;
    constructor(C _c) { c = _c; }

    // We will trigger transferFrom from this contract as the spender. To observe allowance during the transfer,
    // we use the receive() callback: the mutant updates balances before decreasing allowance, and if transferFrom
    // causes an external call into this contract (e.g., via sending Ether) we can re-enter and read allowance.
    // The contract C's transferFrom does not itself send Ether, so to create an observable difference we exploit
    // the fact that transferFrom emits Transfer events but does not call external code. However the mutated order
    // makes allowance temporarily still equal to old value while balances changed; we detect that by making the
    // owner be this contract and doing a transferFrom where _from == address(this) and having this contract
    // check allowance after reentering via a direct call triggered by making the spender and this contract interact.
    // To create a reentrant observation point, we instead rely on calling transferFrom from an address that is a
    // contract (this test) which can, before calling transferFrom, set allowance and then call transferFrom and
    // immediately after the transfer read allowance. The mutant will cause the post-call allowance read to differ
    // (this distinguishes behavior). The assert enforces that after a successful transferFrom, allowance == prev - amt.

    // Note: the function must be payable only if sending Ether; not needed here.
    function run(address _from, uint256 _initialAllowance, address _to, uint256 _amount) public payable {
        // preconditions: this contract is the spender (msg.sender of transferFrom), _from must not be zero and different from this contract
        require(_from != address(0) && _from != address(this));
        // Set up: the owner (_from) must have sufficient balance for the transfer and must have approved this contract.
        // We cannot call internal helpers on C to set balances directly; we assume owner has balance by relying on public functions.
        // So require that _initialAllowance >= _amount and _amount > 0 to make transferFrom allowed by allowance check.
        require(_initialAllowance >= _amount && _amount > 0);

        // Approve this contract as spender from _from: we cannot call C.approve on behalf of _from, so this test assumes
        // that _from has already approved this contract externally in the environment. We cannot enforce that here,
        // so we only guard logical preconditions we can check.
        // The distinguishing observation is: after calling transferFrom, reading allowance() should equal previous - _amount.

        // Call transferFrom as spender (this contract). This call is top-level and mutates C.
        c.transferFrom(_from, _to, _amount);

        // Observe allowance after the call
        uint256 allowAfter = c.allowance(_from, address(this));

        // Also read a value that approximates the previous allowance by adding _amount back to the observed value.
        // If original contract decremented allowance before balances update, then allowAfter == prev - _amount.
        // In the mutant, allowAfter may still equal prev (if balances changed first and an observer could see old value),
        // so the general rule enforces the proper decrease.
        assert(allowAfter + _amount >= allowAfter && allowAfter + _amount - _amount == allowAfter);

        // Finally assert the intended invariant: allowance_after == (some non-negative) value; express as equality to prev - amount
        // We cannot read prev directly, so we require that allowance_after <= _initialAllowance && allowance_after + _amount == _initialAllowance;
        assert(allowAfter + _amount == _initialAllowance);
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address to, address spender, uint256 amount) public payable {
        // Preconditions needed so transferFrom can succeed on the original:
        // require to is not zero, balances[from] >= amount, allowed[from][spender] >= amount
        require(to != address(0));
        // We cannot directly read balances or allowed, but we can require that calling transferFrom does not revert by
        // making a best-effort: the call must succeed (we observe its return). We'll perform the state-changing call and
        // then assert the general relation between allowance and spender balance via public getters.

        bool ok = c.transferFrom(from, to, amount);
        // After a successful transferFrom, read allowance and spender's balance
        uint256 postAllowance = c.allowance(from, spender);
        uint256 postSpenderBal = c.balanceOf(spender);

        // General rule: spender's allowance for from should not be greater than spender's own balance after the transfer
        // (This holds in the original where allowance is decreased before emitting Transfer; the mutant can transiently leave
        // allowance larger than the spender's balance observable immediately after the call.)
        assert(!ok || postAllowance <= postSpenderBal);
    }
}

