contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: ownerAddr (who grants allowance), attackerSalt (distinguishes attacker), amount
    // We fuzz an amount and an owner address; attacker contract is deployed per test (not fuzzed address)
    function testFuzz_property(address ownerAddr, uint256 amount, uint256 attackerSalt) public {
        // Keep domains wide but sensible
        vm.assume(ownerAddr != address(0));
        // bound amount to non-zero and within large range
        amount = bound(amount, 1, type(uint256).max / 2);

        // Deploy attacker helper which will act as spender S and reenter when transferFrom is executing
        ExploitSpender attacker = new ExploitSpender(address(c));

        // Ensure owner has enough tokens to approve and transfer
        // The contract constructor sets owner = deployer (this test contract), and initial balances are given to that owner via XBornID()
        // To allow arbitrary ownerAddr to be the token holder, we transfer tokens from the test deployer to ownerAddr
        // First, ensure the test contract (msg.sender in setUp) has distribution assigned: call XBornID() from deployer
        // XBornID is a public function in C; calling it initializes balances for the deployer (owner)
        // The deployer of C was this test contract (see setUp), so call XBornID as that deployer
        c.XBornID();

        // Give some tokens to ownerAddr so they can approve attacker
        uint256 give = amount > 0 ? amount : 1;
        // transfer from deployer (this) to ownerAddr
        c.transfer(ownerAddr, give);

        // vm.prank to act as ownerAddr when calling approve
        vm.prank(ownerAddr);
        // owner approves attacker for amount
        bool ok = c.approve(address(attacker), amount);
        // approval should succeed on reference implementation
        assertTrue(ok);

        // attacker needs some Ether to be able to reenter if needed (not strictly necessary here)
        vm.deal(address(attacker), 1 ether);

        // Now have attacker attempt to call transferFrom to move tokens from ownerAddr to some recipient (use attacker as recipient)
        // The attacker contract will, in its transferFrom invocation, try to observe allowance via allowance(owner, attacker)
        // and cause a reentrant read during the transferFrom execution to detect ordering differences.

        // Record allowance before
        uint256 beforeAllow = c.allowance(ownerAddr, address(attacker));

        // Start the attacker call: attacker calls doTransferFrom(ownerAddr, recipient, amount)
        // We bound recipient to attacker itself
        address recipient = address(attacker);

        // Call the attacker entrypoint which performs transferFrom on c
        // Use try/catch to capture whether it succeeds; we still assert on final allowance via c.allowance
        bool succeeded;
        try attacker.doTransferFrom{value: 0}(ownerAddr, recipient, amount) {
            succeeded = true;
        } catch {
            succeeded = false;
        }

        // After the operation, reference contract property: allowance decreased by exactly amount (and never negative)
        // So finalAllowance == beforeAllow - (succeeded ? amount : 0)
        uint256 finalAllow = c.allowance(ownerAddr, address(attacker));

        // Single assertion: the reference preserves numeric decrease; the mutant that reorders writes can be observed by the reentrant attacker
        // We assert the expected invariant that should hold for the correct contract (and will fail on the mutant for some inputs):
        if (succeeded) {
            assertTrue(finalAllow + amount == beforeAllow);
        } else {
            // if transferFrom reverted, then allowance must be unchanged
            assertTrue(finalAllow == beforeAllow);
        }
    }
}

// Minimal attacker that reenters to read allowance during transferFrom execution.
// It calls c.transferFrom(...) and in its fallback it will query c.allowance(owner, address(this))
contract ExploitSpender {
    C public token;
    constructor(address tokenAddr) {
        token = C(tokenAddr);
    }

    // This function initiates transferFrom; the contract's fallback may be invoked in the middle depending on mutation
    function doTransferFrom(address from, address to, uint256 amount) public payable {
        // Call transferFrom on token. If the token makes any external calls to recipient that trigger this contract's fallback,
        // the fallback will query allowance and record it (observable by the token if it used transfers that touch external code).
        token.transferFrom(from, to, amount);
    }

    // fallback that reads allowance when invoked
    fallback() external payable {
        // read allowance during any unexpected call into this contract
        // This read itself does not change state but will be observable by the token if token's transfer triggers external calls
        token.allowance(address(0xdead), address(this));
    }
}

