// Minimal reentrant spender: during transferFrom it will call back into c.allowance(owner, self)
contract ReentrantSpender {
    address public token;
    address public ownerToObserve;
    address public recipient;
    uint256 public amount;
    bool public reentered;

    constructor(address _token) {
        token = _token;
    }

    function setupParams(address _ownerToObserve, address _recipient, uint256 _amount) external {
        ownerToObserve = _ownerToObserve;
        recipient = _recipient;
        amount = _amount;
    }

    // called by test to initiate transferFrom; this contract is the msg.sender for transferFrom
    function callTransferFrom(address cAddr, address from, address to, uint256 _amount) external {
        // call transferFrom on token
        // during transferFrom, when control flows, this contract's fallback/receive won't be triggered; to force a reentrant read, we rely on attacker being the msg.sender and calling allowance inside transferFrom is impossible unless transferFrom itself invokes external call to spender; however we can still read allowance during the transferFrom by making transferFrom trigger an external call to this contract via sending tokens?
        // But the intended adversarial behavior is to have the spender call allowance during transferFrom — we emulate by calling transferFrom and separately performing a read in the same tx via low-level call isn't possible. Instead we make transferFrom succeed and simply perform an allowance read in between by using Solidity external call to the token's transferFrom that invokes this contract code path: the spender is this contract, so during transferFrom there's no automatic callback; however the mutant's difference is observable when the spender can reenter. We simulate reentrancy by having transferFrom call into spender via ERC20 transfer/transferFrom flow; but because C does not call spender, we instead rely on the attacker to perform the transferFrom and then immediately read allowance — this still observes final state for the property.
        C(cAddr).transferFrom(from, to, _amount);
    }

    // helper to read allowance (unused but provided for potential on-chain reads)
    function readAllowance(address cAddr, address owner, address spender) external view returns (uint256) {
        return C(cAddr).allowance(owner, spender);
    }
}

