// by calling a view function on the token. To observe the interleaving effect, the
// reentrant contract triggers a call into token.allowance in its fallback via an
// intermediate call path: token.transferFrom will invoke transfer (which emits Transfer)
// but transferFrom itself does not call external code. However, we can make the spender
// be a contract that, before calling transferFrom, sets up state so that when transferFrom
// updates balances it causes a call into the spender contract (not possible here). Instead
// we force the spender contract to be the caller and, during transferFrom execution, we
// rely on the fact that the mutant's reordering can be observed by reading allowance
// after transferFrom returns. The adversarial behavior is simply a contract that calls
// transferFrom and also exposes a helper to read allowance. The distinguishing effect
// requires reentrancy during transferFrom; to enable an observable difference without
// vm.mock, we make the spender contract call transferFrom and inside its call it calls
// back into token.allowance via a separate transaction interleaving is not possible.
// However the known mutant difference requires a reentrant spender that calls back
// into the token during transferFrom; we simulate that by having the spender implement
// a token-compatible function that transferFrom will call (not possible). Given EVM
// semantics and this contract's implementation, the safe universal property that always
// holds on reference (and is broken by the mutant) is: after a successful transferFrom,
// allowance(owner, spender) equals oldAllowance - amount. We assert that for all fuzzed
// inputs. The test deploys a spender contract to act as the caller (so allowance can be
// observed via address) and lets the fuzzer pick owner, to, amount. The fuzzer will find
// an input that makes the mutant behave differently because a reentrant caller can read
// the allowance mid-call; the helper contract is provided so the spender is a contract.

contract InvMutTest is Test {
    C c;
    Caller spender;

    function setUp() public {
        c = new C();
        // Allocate initial distributed tokens to owner (deployer) via the provided initializer
        // The constructor of C set owner = msg.sender (test contract) so we must call XBornID
        // as the owner to set balances[owner] = totalDistributed.
        c.XBornID();
        // Deploy a contract that will act as spender (a contract address instead of EOA)
        spender = new Caller(c);
    }

    // fuzz parameters: owner, to, amount
    function testFuzz_property(address owner, address to, uint256 amount) public {
        // Keep addresses non-zero and distinct where sensible
        vm.assume(owner != address(0));
        vm.assume(to != address(0));

        // Bound amount to a reasonable range so arithmetic doesn't overflow in test logic
        amount = bound(amount, 1, type(uint256).max / 2);

        // Ensure owner has enough balance: make test contract (address(this)) owner of some tokens
        // In setUp we called XBornID from this test contract so this contract has totalDistributed.
        // Transfer tokens from test contract (which currently holds totalDistributed) to owner to set up scenario.
        uint256 supplySenderBal = c.balanceOf(address(this));
        // Ensure we only transfer up to supplySenderBal
        uint256 transferToOwner = amount <= supplySenderBal ? amount : supplySenderBal;
        if (transferToOwner > 0) {
            // transfer to owner
            c.transfer(owner, transferToOwner);
        }

        // Approve the spender contract for at least `amount`
        // We must have the owner perform the approve. Use vm.prank to impersonate owner.
        vm.prank(owner);
        // Approve exactly `amount` (or minimal positive if transferToOwner was zero)
        uint256 approveAmount = amount == 0 ? 1 : amount;
        // call approve(owner -> spender)
        c.approve(address(spender), approveAmount);

        // Record allowance before transferFrom
        uint256 beforeAllow = c.allowance(owner, address(spender));

        // Ensure owner has sufficient balance for the transferFrom: if not, adjust amount to available
        uint256 ownerBal = c.balanceOf(owner);
        uint256 actualAmount = amount;
        if (actualAmount > ownerBal) actualAmount = ownerBal;
        if (actualAmount == 0 || beforeAllow < actualAmount) {
            // nothing to test: the reference requires preconditions; skip by assuming admissible domain
            vm.assume(actualAmount > 0 && beforeAllow >= actualAmount);
        }

        // Now have the spender contract call transferFrom(owner, to, actualAmount)
        // The caller is a contract (spender) so any difference involving contract callers is possible.
        // Record allowance after transferFrom
        vm.prank(address(spender));
        bool ok = spender.invokeTransferFrom(owner, to, actualAmount);
        // require transferFrom succeeded in order to observe final allowance
        vm.assume(ok);

        uint256 afterAllow = c.allowance(owner, address(spender));

        // The universal property: reference always decreases allowance by exactly actualAmount
        // i.e., afterAllow == beforeAllow - actualAmount
        assertTrue(afterAllow == beforeAllow - actualAmount);
    }
}

// Helper spender contract that simply calls transferFrom on the token and exposes a helper
contract Caller {
    C token;
    constructor(C _token) {
        token = _token;
    }
    function invokeTransferFrom(address from, address to, uint256 amount) public returns (bool) {
        try token.transferFrom(from, to, amount) returns (bool r) {
            return r;
        } catch {
            return false;
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: owner funds ownerAddr initialApproveAmount transferAmount spenderAddr
    function run(address ownerAddr, address spenderAddr, uint256 initialApproveAmount, uint256 transferAmount) public {
        // Preconditions to make meaningful calls
        require(ownerAddr != address(0) && spenderAddr != address(0));
        require(spenderAddr != ownerAddr);
        require(initialApproveAmount >= transferAmount && transferAmount > 0);

        // 1) Ensure owner has enough balance distributed to cover the approve+transferFrom.
        // Call getTokens from ownerAddr to receive tokens: must be allowed by whitelist, so first ensure ownerAddr not blacklisted by invoking from that address is impossible here.
        // Instead, use c.transferOwnership to make this contract the owner, then have owner (this contract) hold tokens by relying on initial totalDistributed assigned to original owner.
        // Transfer some tokens from the contract's current owner to ownerAddr so ownerAddr has balance. To effect that, we must be the owner to call transferOwnership; we cannot assume msg.sender equals original owner, so instead require that this contract already has enough balance via c.balanceOf(address(this)).
        // Simpler approach: operate using addresses that perform approve/transferFrom from existing balances: use c.balanceOf(address(this)) as the source funds.

        uint256 srcBalance = c.balanceOf(address(this));
        require(srcBalance >= transferAmount, "test contract lacks tokens to fund transferFrom");

        // 2) Approve spenderAddr to spend initialApproveAmount from this contract's balance
        bool ok = c.approve(spenderAddr, initialApproveAmount);
        require(ok, "approve failed");

        // 3) As spenderAddr, call transferFrom to move transferAmount from this contract to ownerAddr.
        // We cannot change msg.sender in solidity, but transferFrom uses msg.sender for allowance check; to simulate spenderAddr calling, we rely on the public interface: call c.transferFrom from this contract only if this contract is the spender.
        // So instead set spenderAddr == address(this) by requiring that in preconditions.
        require(spenderAddr == address(this), "spender must be this contract for transferFrom call");

        // Perform transferFrom: this contract (spender) transfers from this contract (owner of tokens) to ownerAddr
        bool tf = c.transferFrom(address(this), ownerAddr, transferAmount);
        require(tf, "transferFrom failed");

        // Observe allowance after transferFrom via public allowance getter
        uint256 remaining = c.allowance(address(this), address(this));

        // On original contract P, allowance decreases by transferAmount, so remaining == initialApproveAmount - transferAmount.
        // On mutant M, allowance is unchanged, so remaining == initialApproveAmount — therefore the assertion distinguishes P vs M.
        assert(remaining == (initialApproveAmount - transferAmount));
    }

    // allow contract to receive ether if needed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // params: owner, spender, recipient, initialAllowance, firstAmount, secondAmount
    function run(address owner, address spender, address recipient, uint256 initialAllowance, uint256 firstAmount, uint256 secondAmount) public payable {
        require(owner != address(0) && spender != address(0) && recipient != address(0));
        // Preconditions: set amounts so both transfers individually are <= initialAllowance,
        // but their sum is > initialAllowance, so original contract should prevent second transferFrom.
        require(firstAmount <= initialAllowance && secondAmount <= initialAllowance);
        require(firstAmount + secondAmount > initialAllowance);

        // Prepare: caller must be owner to approve; use c.transferFrom from spender, so the test uses c.approve from owner.
        // We cannot perform actions as other addresses here; instead we rely on public surface only.
        // The contract C uses msg.sender as owner in constructor; to get an allowance, we first need owner to approve spender.
        // So require that msg.sender is the owner and will perform approve. The test will use msg.sender to act as the token holder.
        // Ensure msg.sender has enough balance: rely on existing distribution; require balance >= initialAllowance
        require(c.balanceOf(msg.sender) >= initialAllowance);

        // Approve 'spender' to spend initialAllowance from msg.sender's balance
        bool ok = c.approve(spender, initialAllowance);
        require(ok);

        // first transferFrom executed by this test must be invoked as the spender; but we cannot change msg.sender mid-function.
        // Instead, we use the public interface: try to observe difference by calling transferFrom as this contract acting as spender.
        // So we must have previously been approved as spender. Approve this contract (address(this)) by msg.sender.
        // Adjust: approve address(this) as spender and then perform two transferFrom calls from address(this).
        ok = c.approve(address(this), initialAllowance);
        require(ok);

        // First transferFrom from msg.sender to recipient of firstAmount
        c.transferFrom(msg.sender, recipient, firstAmount);
        // Second transferFrom from msg.sender to recipient of secondAmount
        c.transferFrom(msg.sender, recipient, secondAmount);

        // In the original contract, after the two calls, the remaining allowance for this contract is initialAllowance - firstAmount - secondAmount,
        // but since firstAmount + secondAmount > initialAllowance, the second transferFrom should have reverted in the original, so reaching here means mutant allowed overspend.
        // We cannot read allowed directly; instead we check that the sum of tokens moved from sender exceeds his initial balance reduction allowed by initialAllowance.
        // Observe balances: sender's balance decreased by (firstAmount + secondAmount) and recipient increased accordingly.
        uint256 senderBal = c.balanceOf(msg.sender);
        uint256 recipientBal = c.balanceOf(recipient);

        // The rule: sender's balance must be >= initialBalance - initialAllowance (i.e., spender cannot withdraw more than allowance in total).
        // Compute initialBalance as senderBal + firstAmount + secondAmount (since we performed two transfers).
        // So assert that total withdrawn (first+second) <= initialAllowance. This holds in original, violated in mutant.
        assert((firstAmount + secondAmount) <= initialAllowance);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address owner, address spender, address to, uint256 amount, uint256 initialAllowance) public payable {
        require(owner != address(0) && spender != address(0) && to != address(0));
        // set up: owner must have enough balance and must have approved spender with initialAllowance
        // We cannot call internal functions to set balances, but we rely on public interface: assume owner has sufficient balance and approval already in the contract state for the chosen parameters.
        // Precondition: allowance at start equals initialAllowance (caller must choose parameters consistent with contract state)
        uint256 before = c.allowance(owner, spender);
        require(before >= amount && before == initialAllowance);

        // perform the transferFrom which should decrement the allowance in the original contract
        bool success = c.transferFrom(owner, to, amount);

        uint256 after = c.allowance(owner, spender);
        // General rule: after a successful transferFrom, the allowance should decrease by exactly amount
        assert(success && after + amount == before);
    }
    receive() external payable { }
}

