        require(spenderAddr != address(0) && to != address(0));
        uint256 beforeAllow = c.allowance(ownerAddr, spenderAddr);
        require(beforeAllow >= amount);
        uint256 ownerBal = c.balanceOf(ownerAddr);
        require(ownerBal >= amount);

        // perform the transferFrom as the current msg.sender (spenderAddr should be the caller in a real scenario,
        // but we cannot change msg.sender here; we rely on the contract's public surface to observe allowance change,
        // so we call transferFrom and observe allowance change regardless of who initiated it).
        // Note: The test focuses on allowance values observable before and after the call.
        c.transferFrom(ownerAddr, to, amount);

        uint256 afterAllow = c.allowance(ownerAddr, spenderAddr);
        // General rule: allowance must not increase after transferFrom (should stay same or decrease in the original)
        assert(afterAllow <= beforeAllow);
    }
