}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // params: owner, spender (msg.sender in original call), recipient, amount
    function run(address ownerAddr, address recipient, uint256 amount) public payable {
        // preconditions: ownerAddr != address(0), recipient != address(0), amount > 0
        // also require that this contract has been approved by ownerAddr for >= 2*amount
        require(ownerAddr != address(0) && recipient != address(0) && amount > 0);
        // ensure allowance is sufficient for two sequential transfers of `amount`
        require(c.allowance(ownerAddr, address(this)) >= amount * 2);
        // ensure owner has enough balance for both transfers
        require(c.balanceOf(ownerAddr) >= amount * 2);

        // First transferFrom should succeed
        bool ok1 = false;
        try c.transferFrom(ownerAddr, recipient, amount) { ok1 = true; } catch { ok1 = false; }

        // Second transferFrom of same amount should revert (not succeed) because allowance was decreased by first call in original
        bool ok2 = false;
        try c.transferFrom(ownerAddr, recipient, amount) { ok2 = true; } catch { ok2 = false; }

        // In original contract P: first succeeds and second fails because allowance was reduced.
        // The property: not both transfers succeed. Express as: !(ok1 && ok2)
        assert(!(ok1 && ok2));
    }
    receive() external payable { }
}
